{
  "template": "trigger"
}

namespace dose;
// True parameters per compound; responses are compounds x concentrations x replicates.
table Plate {
  names:[string];
  bottom:[double];
  top:[double];
  ec50:[double];
  hill:[double];
  conc:[double];
  replicates:ulong;
  response:[double];
  seed:ulong;
  noise_sd:double;
  dilution:double;
}
table Outputs { plate:Plate (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ps.matplotlib ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 42
    },
    {
      "name": "noise_sd",
      "type": "double",
      "data": 4.0
    },
    {
      "name": "concentrations",
      "type": "uint64",
      "data": 8
    },
    {
      "name": "top_um",
      "type": "double",
      "data": 100.0
    },
    {
      "name": "dilution",
      "type": "double",
      "data": 3.16
    },
    {
      "name": "replicates",
      "type": "uint64",
      "data": 3
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "fit",
        "bootstrap",
        "range"
      ]
    }
  ]
}

namespace dose;
// One row per compound: bottom, top, log10 EC50, Hill slope.
table Fit { params:[double]; residual_sd:[double]; }
table Outputs { fit:Fit (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ps.scipy ps.matplotlib ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "plate"
    }
  ]
}

namespace dose;
// Per compound: EC50 and Hill slope with their intervals, the true values and
// the bootstrap samples (compounds x n_boot).
table Intervals {
  names:[string];
  ec50:[double];
  ec50_low:[double];
  ec50_high:[double];
  ec50_true:[double];
  hill:[double];
  hill_low:[double];
  hill_high:[double];
  hill_true:[double];
  n_boot:ulong;
  log_ec50_samples:[double];
  hill_samples:[double];
  conc_low:double;
  conc_high:double;
}
table Outputs { intervals:Intervals (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
